using UnityEngine;

public class Player_JumpState : PlayerState
{
    public Player_JumpState(Player player, StateMachine stateMachine, string animBoolName)
        : base(player, stateMachine, animBoolName) { }

    public override void Enter()
    {
        base.Enter();
        rb.velocity = new Vector2(rb.velocity.x, player.jumpForce);
    }

    public override void Update()
    {
        base.Update();

        player.SetVelocity(moveInput.x * player.moveSpeed, rb.velocity.y);

        if (rb.velocity.y <= 0)
            stateMachine.ChangeState(player.fallState);
    }
}

using UnityEngine;
using PlayerInputSet = PlayerInput.PlayerInput;

public class Player : Entity
{
    public PlayerInputSet input { get; private set; }

    public Vector2 moveInput { get; private set; }

    #region 玩家状态
    public Player_IdleState idleState { get; private set; }
    public Player_MoveState moveState { get; private set; }
    public Player_JumpState jumpState { get; private set; }
    public Player_FallState fallState { get; private set; }
    #endregion

    #region 移动相关参数
    [Header("Movement details")]
    public float moveSpeed = 5f;
    public float jumpForce = 8f;
    #endregion

    protected override void Awake()
    {
        base.Awake();

        input = new PlayerInputSet();

        idleState = new Player_IdleState(this, stateMachine, "Idle");
        moveState = new Player_MoveState(this, stateMachine, "Move");
        jumpState = new Player_JumpState(this, stateMachine, "Jumo");
        fallState = new Player_FallState(this, stateMachine, "Fall");
    }

    protected override void Start()
    {
        base.Start();
        stateMachine.Initialize(idleState);
    }

    private void OnEnable()
    {
        input.Enable();

        input.Player.Move.performed += ctx => moveInput = ctx.ReadValue<Vector2>();
        input.Player.Move.canceled += ctx => moveInput = Vector2.zero;
    }

    private void OnDisable()
    {
        input.Disable();
    }
}

using UnityEngine;
using PlayerInputSet = PlayerInput.PlayerInput;

public abstract class PlayerState : EntityState
{
    protected Player player;

    protected PlayerInputSet input;

    protected Vector2 moveInput;

    public PlayerState(Player player, StateMachine stateMachine, string animBoolName)
        : base(stateMachine, animBoolName)
    {
        this.player = player;

        this.anim = player.anim;
        this.rb = player.rb;
        this.input = player.input;
    }

    public override void Update()
    {
        base.Update();

        moveInput = player.moveInput;
    }

    public override void UpdateAnimationParameters()
    {
        base.UpdateAnimationParameters();

        anim.SetFloat("yVelocity", rb.velocity.y);
    }
}

