using UnityEngine;

public class Player_FallState : PlayerState
{
    public Player_FallState(Player player, StateMachine stateMachine, string animBoolName)
        : base(player, stateMachine, animBoolName) { }

    public override void Update()
    {
        base.Update();

        player.SetVelocity(moveInput.x * player.moveSpeed, rb.velocity.y);

        if (player.groundDetected)
        {
            if (moveInput.x != 0)
                stateMachine.ChangeState(player.moveState);
            else
                stateMachine.ChangeState(player.idleState);
        }
    }
}

public class Player_MoveState : PlayerState
{
    public Player_MoveState(Player player, StateMachine stateMachine, string animBoolName)
        : base(player, stateMachine, animBoolName) { }

    public override void Update()
    {
        base.Update();

        player.SetVelocity(moveInput.x * player.moveSpeed, rb.velocity.y);

        if (moveInput.x == 0)
            stateMachine.ChangeState(player.idleState);
        else if (input.Player.Jump.WasPressedThisFrame() && player.groundDetected)
            stateMachine.ChangeState(player.jumpState);
        else if (!player.groundDetected)
            stateMachine.ChangeState(player.fallState);
    }
}

public class Player_IdleState : PlayerState
{
    public Player_IdleState(Player player, StateMachine stateMachine, string animBoolName)
        : base(player, stateMachine, animBoolName) { }

    public override void Enter()
    {
        base.Enter();
        player.SetVelocity(0, rb.velocity.y);
    }

    public override void Update()
    {
        base.Update();

        if (moveInput.x != 0)
            stateMachine.ChangeState(player.moveState);
        else if (input.Player.Jump.WasPressedThisFrame() && player.groundDetected)
            stateMachine.ChangeState(player.jumpState);
        else if (!player.groundDetected)
            stateMachine.ChangeState(player.fallState);
    }
}

using UnityEngine;

public class Entity : MonoBehaviour
{
    public Animator anim { get; private set; }
    public Rigidbody2D rb { get; private set; }
    public StateMachine stateMachine { get; private set; }

    [Header("Collision info")]
    [SerializeField] protected LayerMask whatIsGround;
    [SerializeField] protected float groundCheckDistance = 0.3f;
    [SerializeField] protected float wallCheckDistance = 0.5f;
    [SerializeField] protected Transform wallCheck;

    public bool groundDetected { get; protected set; }
    public bool wallDetected { get; protected set; }
    public int facingDir { get; private set; } = 1;

    protected virtual void Awake()
    {
        anim = GetComponentInChildren<Animator>();
        rb = GetComponent<Rigidbody2D>();
        stateMachine = new StateMachine();
    }

    protected virtual void Start()
    {
    }

    protected virtual void Update()
    {
        stateMachine.UpdateActiveState();
        CheckCollision();
    }

    private void CheckCollision()
    {
        Collider2D col = GetComponent<Collider2D>();
        if (col != null)
        {
            Vector2 origin = new Vector2(transform.position.x, col.bounds.min.y);
            groundDetected = Physics2D.Raycast(origin, Vector2.down, groundCheckDistance, whatIsGround);
        }

        if (wallCheck != null)
        {
            wallDetected = Physics2D.Raycast(wallCheck.position, Vector2.right * facingDir, wallCheckDistance, whatIsGround);
        }
    }

    public void SetVelocity(float xVelocity, float yVelocity)
    {
        rb.velocity = new Vector2(xVelocity, yVelocity);
        HandleFlip(xVelocity);
    }

    public void HandleFlip(float xVelocity)
    {
        if (xVelocity > 0 && facingDir == -1)
            Flip();
        else if (xVelocity < 0 && facingDir == 1)
            Flip();
    }

    protected void Flip()
    {
        facingDir *= -1;
        transform.Rotate(0, 180, 0);
    }

    protected virtual void OnDrawGizmos()
    {
        Collider2D col = GetComponent<Collider2D>();
        if (col != null)
        {
            Gizmos.color = Color.green;
            Vector2 origin = new Vector2(transform.position.x, col.bounds.min.y);
            Gizmos.DrawLine(origin, origin + Vector2.down * groundCheckDistance);
        }

        if (wallCheck != null)
        {
            Gizmos.color = Color.blue;
            Gizmos.DrawLine(wallCheck.position, wallCheck.position + Vector3.right * facingDir * wallCheckDistance);
        }
    }
}

