    public Animator anim { get; private set; }
    public Rigidbody2D rb { get; private set; }
    public StateMachine stateMachine { get; private set; }

    [Header("Collision info")]
    [SerializeField] protected LayerMask whatIsGround;
    [SerializeField] protected float groundCheckDistance = 0.3f;
    [SerializeField] protected float wallCheckDistance = 0.5f;
    [SerializeField] protected Transform wallCheck;

    public bool groundDetected { get; protected set; }
    public bool wallDetected { get; protected set; }
    public int facingDir { get; private set; } = 1;

    protected virtual void Awake()
    {
        anim = GetComponentInChildren<Animator>();
        rb = GetComponent<Rigidbody2D>();
        stateMachine = new StateMachine();
    }

    protected virtual void Start()
    {
    }

    protected virtual void Update()
    {
        stateMachine.UpdateActiveState();
        CheckCollision();
    }

    private void CheckCollision()
    {
        Collider2D col = GetComponent<Collider2D>();
        if (col != null)
        {
            Vector2 origin = new Vector2(transform.position.x, col.bounds.min.y);
            groundDetected = Physics2D.Raycast(origin, Vector2.down, groundCheckDistance, whatIsGround);
        }

        if (wallCheck != null)
        {
            wallDetected = Physics2D.Raycast(wallCheck.position, Vector2.right * facingDir, wallCheckDistance, whatIsGround);
        }
    }

    public void SetVelocity(float xVelocity, float yVelocity)
    {
        rb.velocity = new Vector2(xVelocity, yVelocity);
        HandleFlip(xVelocity);
    }

    public void HandleFlip(float xVelocity)
    {
        if (xVelocity > 0 && facingDir == -1)
            Flip();
        else if (xVelocity < 0 && facingDir == 1)
            Flip();
    }

    protected void Flip()
    {
        facingDir *= -1;
        transform.Rotate(0, 180, 0);
    }

    protected virtual void OnDrawGizmos()
    {
        Collider2D col = GetComponent<Collider2D>();
        if (col != null)
        {
            Gizmos.color = Color.green;
            Vector2 origin = new Vector2(transform.position.x, col.bounds.min.y);
            Gizmos.DrawLine(origin, origin + Vector2.down * groundCheckDistance);
        }

        if (wallCheck != null)
        {
            Gizmos.color = Color.blue;
            Gizmos.DrawLine(wallCheck.position, wallCheck.position + Vector3.right * facingDir * wallCheckDistance);
        }
    }
}

using UnityEngine;

public abstract class EntityState
{
    protected StateMachine stateMachine;

    protected string animBoolName;

    protected Animator anim;

    protected Rigidbody2D rb;

    protected float stateTimer;

    protected bool triggerCalled;

    public EntityState(StateMachine stateMachine, string animBoolName)
    {
        this.stateMachine = stateMachine;
        this.animBoolName = animBoolName;
    }

    public virtual void Enter()
    {
        if (!string.IsNullOrEmpty(animBoolName))
            anim.SetBool(animBoolName, true);

        triggerCalled = false;
    }

    public virtual void Update()
    {
        stateTimer -= Time.deltaTime;
        UpdateAnimationParameters();
    }

    public virtual void Exit()
    {
        if (!string.IsNullOrEmpty(animBoolName))
            anim.SetBool(animBoolName, false);
    }

    public void CallAnimationTrigger()
    {
        triggerCalled = true;
    }

    public virtual void UpdateAnimationParameters()
    {
    }
}

using UnityEngine;

public class StateMachine
{
    public EntityState currentState { get; private set; }

    public bool canChangeState = true;

    public void Initialize(EntityState startingState)
    {
        currentState = startingState;
        currentState.Enter();
    }

    public void ChangeState(EntityState newState)
    {
        if (canChangeState == false)
            return;

        currentState.Exit();
        currentState = newState;
        currentState.Enter();
    }

    public void UpdateActiveState()
    {
        currentState.Update();
    }

    public void SwitchOffStateMachine() => canChangeState = false;
}

using UnityEngine;

public class Player_JumpState : PlayerState
{
    public Player_JumpState(Player player, StateMachine stateMachine, string animBoolName)
        : base(player, stateMachine, animBoolName) { }

    public override void Enter()
    {
        base.Enter();
        rb.velocity = new Vector2(rb.velocity.x, player.jumpForce);
    }

    public override void Update()
    {
        base.Update();

        player.SetVelocity(moveInput.x * player.moveSpeed, rb.velocity.y);

        if (rb.velocity.y <= 0)
            stateMachine.ChangeState(player.fallState);
    }
}

using UnityEngine;
using PlayerInputSet = PlayerInput.PlayerInput;

public class Player : Entity
{
    public PlayerInputSet input { get; private set; }

    public Vector2 moveInput { get; private set; }

    #region 玩家状态
    public Player_IdleState idleState { get; private set; }
    public Player_MoveState moveState { get; private set; }
    public Player_JumpState jumpState { get; private set; }
    public Player_FallState fallState { get; private set; }
    #endregion

    #region 移动相关参数
    [Header("Movement details")]
    public float moveSpeed = 5f;
    public float jumpForce = 8f;
    #endregion

    protected override void Awake()
    {
        base.Awake();

        input = new PlayerInputSet();

        idleState = new Player_IdleState(this, stateMachine, "Idle");
        moveState = new Player_MoveState(this, stateMachine, "Move");
        jumpState = new Player_JumpState(this, stateMachine, "Jumo");
        fallState = new Player_FallState(this, stateMachine, "Fall");
    }

    protected override void Start()
    {
        base.Start();
        stateMachine.Initialize(idleState);
    }

    private void OnEnable()
    {
        input.Enable();

        input.Player.Move.performed += ctx => moveInput = ctx.ReadValue<Vector2>();
        input.Player.Move.canceled += ctx => moveInput = Vector2.zero;
    }

    private void OnDisable()
    {
        input.Disable();
    }
}

using UnityEngine;
